  if (typeof text !== 'string') return [];
  if (text === '') return [];

  const records = [];
  let currentRecord = '';
  let inQuotes = false;
  let i = 0;

  while (i <= text.length) {
    const char = text[i];

    if (i === text.length) {
      // End of input
      if (currentRecord !== '') {
        records.push(currentRecord.split(',').map(f => f.trim()));
      }
      break;
