        currentRecord += '"';
        i += 2;
        continue;
      } else {
        inQuotes = !inQuotes;
        if (inQuotes) {
          currentRecord += '"';
        } else {
          // End of quoted field
          currentRecord += '"';
        }
        i++;
        continue;
      }
    }

    if (char === '\n') {
      // End of record
      records.push(currentRecord.split(',').map(f => f.trim()));
      currentRecord = '';
      i++;
      continue;
    }

    if (char === ',' && !inQuotes) {
      records.push(currentRecord.split(',').map(f => f.trim()));
      currentRecord = '';
      i++;
      continue;
    }

    currentRecord += char;
    i++;
  }

  return records;
}
```

